async function carregarUsuarios(){try{const a=await fetch("/api/admin/usuarios");if(403===a.status||401===a.status)return await Swal.fire("Acesso Negado","Você não tem permissão para acessar esta página.","error"),void(window.location.href="/");const e=await a.json();e.sucesso&&renderizarUsuarios(e.dados)}catch{Swal.fire("Erro","Erro ao carregar dados. Tente novamente.","error")}}function criarCelula(a){const e=document.createElement("td");return e.textContent=a??"",e}function renderizarUsuarios(a){const e=document.querySelector("#tabelaUsuarios tbody");if(e.replaceChildren(),!a.length){const a=e.insertRow().insertCell();return a.colSpan=7,void(a.textContent="Nenhum usuário encontrado.")}for(const r of a){const a=document.createElement("tr");a.append(criarCelula(r.id),criarCelula(r.nome),criarCelula(r.email),criarCelula(r.saldo_moedas),criarCelula(r.status),criarCelula(r.ganhos_afiliado??0));const t=document.createElement("td"),o=document.createElement("button");o.className="btn btn-warning btn-sm fw-bold",o.textContent="+ Dar Moedas",o.addEventListener("click",()=>darTokens(r.id)),t.className="text-end",t.append(o),a.append(t),e.append(a)}}async function darTokens(a){const{value:e}=await Swal.fire({title:"Adicionar Moedas",text:`Quantas moedas deseja adicionar ao usuário ID ${a}?`,input:"number",showCancelButton:!0,confirmButtonText:"Adicionar",cancelButtonText:"Cancelar",inputValidator:a=>{if(!a||parseInt(a,10)<=0)return"Insira uma quantidade válida!"}});if(!e)return;const r=parseInt(e,10);try{const e=await fetch("/api/admin/usuarios/moedas",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({usuarioId:a,quantidade:r})}),t=await e.json();t.sucesso?(await Swal.fire("Sucesso!","Moedas adicionadas com sucesso!","success"),carregarUsuarios()):Swal.fire("Erro",t.erro||"Falha ao adicionar moedas","error")}catch{Swal.fire("Erro","Erro de conexão ao adicionar moedas.","error")}}document.addEventListener("DOMContentLoaded",carregarUsuarios);